pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 15
        c.SetMinSum(15);
        c.Initialized();

        // User puts 15 ETH with lockTime=0
        address user = address(0x1234);
        vm.deal(user, 15 ether);
        vm.prank(user);
        c.Put{value: 15 ether}(0);

        // Warp past unlock time (block.timestamp + 0 = block.timestamp, so any warp > block.timestamp works)
        vm.warp(block.timestamp + 1);

        // Try Collect(15) and check if it reverts
        bool success;
        vm.prank(user);
        try c.Collect(15 ether) {
            success = true;
        } catch {
            success = false;
        }

        // Reference: MinSum=15, balance=15, so Collect succeeds -> success=true
        // Mutant: MinSum=16, balance=15 < 16, so Collect reverts -> success=false
        assertTrue(success);
    }
}

