        // user deposits 5 wei with lockTime=0, so unlockTime = 1000
        address user = address(0x123);
        vm.deal(user, 5);
        vm.prank(user);
        c.Put{value: 5}(0);
        // now user calls Collect(5). In reference: MinSum=3, balance=5 >=3 and >=5, block.timestamp>1000? actually block.timestamp is 1000, unlockTime=1000, condition block.timestamp > acc.unlockTime (1000 > 1000 is false) so Collect reverts. Need block.timestamp > unlockTime, so warp to 1001 first.
        vm.warp(1001);
        // now call Collect(5)
        bool ok;
        vm.prank(user);
        try c.Collect(5) { ok = true; } catch { ok = false; }
        // In reference, MinSum=3, balance=5 >=3 and >=5, block.timestamp=1001 > unlockTime=1000, so Collect succeeds -> ok=true
        // In bug, MinSum=3*2=6, balance=5 < 6 -> first condition fails -> Collect reverts -> ok=false
