import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 5 before initialization
        c.SetMinSum(5);
        c.Initialized();
        // Give some ether to the contract so Collect can succeed
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.Put(0); // 0 lock time, put 0 ether (fallback not used)
        // Perform a Collect that will succeed in both versions
        // In reference, MinSum is 5; in bug, MinSum is 0
        // The balance after Put is 0 wei (msg.value=0), so Collect(1) will revert because balance < _am.
        // Actually, we need the Collect to succeed to see the divergence.
        // Let's send 1 wei with Put:
        vm.deal(address(this), 1);
        vm.prank(address(this));
        c.Put{value: 1}(0);
        // Now Collect(1): in bug, MinSum=0, balance>=MinSum and balance>=1 and time > unlockTime (block.timestamp > 0) so it succeeds.
        // In reference, MinSum=5, balance=1 < MinSum, so it reverts.
        // After call, in bug contract receives 1 wei, then transfers it back, MinSum stays 0.
        // In reference, Collect reverts, state unchanged, MinSum=5.
        // But the difference statement says P.MinSum() != M.MinSum() after Collect.
        // After successful Collect in bug, MinSum=0; after reverted Collect in reference, MinSum=5. So condition holds.
        vm.warp(1000); // advance time past unlockTime
        vm.prank(address(this));
        try c.Collect(1) {
            // success in bug
        } catch {
            // revert in reference
        }
        // Now assert: reference has c.MinSum() == 5, bug has 0.
        // We assert that c.MinSum() == 0 — this will be true only for the bug.
        assertTrue(c.MinSum() == 0);
    }
}

